          ),
          // Horizontal rule
          hr: () => <hr className="border-border my-3" />,
          // Tables
          table: ({ children }) => (
            <div className="overflow-x-auto my-2 rounded-lg border border-border">
              <table className="min-w-full text-[12px]">{children}</table>
            </div>
          ),
          thead: ({ children }) => <thead className="bg-surface-3">{children}</thead>,
          th: ({ children }) => <th className="px-3 py-1.5 text-left font-semibold text-text border-b border-border">{children}</th>,
          td: ({ children }) => <td className="px-3 py-1.5 text-text-secondary border-b border-border/50">{children}</td>,
          // Pre - handled by code component
          pre: ({ children }) => <>{children}</>,
        }}
      >
        {content}
      </ReactMarkdown>
    </div>
  )
})

export default MarkdownRenderer

