// ─── Restore on open ───────────────────────────────────────────────────

const restoredRef = useRef(false)
useEffect(() => {
  if (open) {
    loadHistory()
    loadContext()
    if (!restoredRef.current && messages.length === 0) {
      restoredRef.current = true
      const savedId = localStorage.getItem('claude-hub:active-session')
      const savedMsgs = localStorage.getItem('claude-hub:active-messages')

      // Case 1: Messages in localStorage (fastest restore — works even without sessionId)
      if (savedMsgs) {
        try {
          const parsed = JSON.parse(savedMsgs) as AiMessage[]
          if (parsed.length > 0) {
            scrollInstantRef.current = true
            if (savedId) setSessionId(savedId)
            setMessages(parsed)
            // Sync with server in background
            if (savedId) getAiSession(savedId).catch(() => {})
            return
          }
        } catch {}
      }

      // Case 2: Only sessionId — fetch from server
      if (savedId) {
        getAiSession(savedId)
          .then(session => {
            scrollInstantRef.current = true
            setSessionId(session.id)
            setMessages(session.messages)
            // Also cache to localStorage for next time
            localStorage.setItem('claude-hub:active-messages', JSON.stringify(session.messages))
          })
          .catch(() => {
            localStorage.removeItem('claude-hub:active-session')
          })
        return
      }
    }
    if (messages.length > 0) scrollInstantRef.current = true
    setTimeout(() => {
      messagesEndRef.current?.scrollIntoView({ behavior: 'instant' })
      inputRef.current?.focus()
    }, 80)
  }
// eslint-disable-next-line react-hooks/exhaustive-deps
}, [open])

