// ─── Restore on open ───────────────────────────────────────────────────

const hasOpenedRef = useRef(false)
const restoredRef = useRef(false)
useEffect(() => {
  if (!open) return

  // First open — restore session from localStorage synchronously (no re-render lag)
  if (!restoredRef.current && messages.length === 0) {
    restoredRef.current = true
    const savedId = localStorage.getItem('claude-hub:active-session')
    const savedMsgs = localStorage.getItem('claude-hub:active-messages')

    if (savedMsgs) {
      try {
        const parsed = JSON.parse(savedMsgs) as AiMessage[]
        if (parsed.length > 0) {
          scrollInstantRef.current = true
          if (savedId) setSessionId(savedId)
          setMessages(parsed)
          if (savedId) getAiSession(savedId).catch(() => {})
        }
      } catch {}
    } else if (savedId) {
      getAiSession(savedId)
        .then(session => {
          scrollInstantRef.current = true
          setSessionId(session.id)
          setMessages(session.messages)
          localStorage.setItem('claude-hub:active-messages', JSON.stringify(session.messages))
        })
        .catch(() => localStorage.removeItem('claude-hub:active-session'))
    }
  }

  // Defer heavy data loading until after the transition completes (200ms)
  if (!hasOpenedRef.current) {
    hasOpenedRef.current = true
    setTimeout(() => {
      loadHistory()
      loadContext()
    }, 220)
  } else {
    // Subsequent opens — refresh history in background
    loadHistory()
  }

  // Focus input after transition
  setTimeout(() => {
    if (messages.length > 0) {
      messagesEndRef.current?.scrollIntoView({ behavior: 'instant' })
    }
    inputRef.current?.focus()
  }, 210)
// eslint-disable-next-line react-hooks/exhaustive-deps
}, [open])

