import { useState, useCallback, useRef, useEffect } from 'react'
import {
  Play, Copy, Trash2, Loader, CheckCircle, AlertCircle,
  ChevronDown, RotateCcw, Clock, Sparkles,
} from 'lucide-react'
import { getUnifiedAgents } from '../lib/api'
import { useApi } from '../hooks/useApi'
import { toast } from '../components/Toast'
import AgentIcon from '../components/AgentIcon'

interface TestResult {
  id: string
  agent: string
  prompt: string
  output: string
  duration: number
  status: 'success' | 'error'
  timestamp: Date
}

export default function Playground() {
  const { data: agents } = useApi(getUnifiedAgents)
  const [selectedAgent, setSelectedAgent] = useState<string>('')
  const [prompt, setPrompt] = useState('')
  const [running, setRunning] = useState(false)
  const [output, setOutput] = useState('')
  const [history, setHistory] = useState<TestResult[]>([])
  const [showAgentPicker, setShowAgentPicker] = useState(false)
  const [agentFilter, setAgentFilter] = useState('')
  const outputRef = useRef<HTMLPreElement>(null)
  const abortRef = useRef<AbortController | null>(null)
  const startTimeRef = useRef<number>(0)

  const globalAgents = (agents || []).filter(a => a.scope === 'global')
  const filteredAgents = globalAgents.filter(a =>
    a.name.toLowerCase().includes(agentFilter.toLowerCase())
  )
  const currentAgent = globalAgents.find(a => a.name === selectedAgent || a.filename === selectedAgent)

  useEffect(() => {
    outputRef.current?.scrollTo({ top: outputRef.current.scrollHeight, behavior: 'smooth' })
  }, [output])

  const runTest = useCallback(async () => {
    if (!prompt.trim()) { toast('error', 'Enter a test prompt'); return }
    setRunning(true)
    setOutput('')
    startTimeRef.current = Date.now()
    abortRef.current = new AbortController()

    try {
      const response = await fetch('/api/playground/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          agentName: selectedAgent || undefined,
          prompt: prompt.trim(),
        }),
        signal: abortRef.current.signal,
      })

      if (!response.body) throw new Error('No response body')
      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''
      let finalOutput = ''

      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        buffer += decoder.decode(value, { stream: true })
        const parts = buffer.split('\n')
        buffer = parts.pop() ?? ''

        for (const line of parts) {
          const trimmed = line.trim()
          if (!trimmed.startsWith('data: ')) continue
          try {
            const event = JSON.parse(trimmed.slice(6))
            if (event.type === 'done' || event.type === 'complete') {
              finalOutput = event.output || ''
              setOutput(finalOutput)
            }
            if (event.type === 'error') {
              setOutput(`Error: ${event.error}`)
              finalOutput = `Error: ${event.error}`
            }
          } catch {}
        }
      }

      // Flush remaining buffer
      if (buffer.trim()) {
        for (const line of buffer.split('\n')) {
          const trimmed = line.trim()
          if (!trimmed.startsWith('data: ')) continue
          try {
            const event = JSON.parse(trimmed.slice(6))
            if (event.type === 'done' || event.type === 'complete') {
              finalOutput = event.output || ''
              setOutput(finalOutput)
            }
            if (event.type === 'error') {
              finalOutput = `Error: ${event.error}`
              setOutput(finalOutput)
            }
          } catch {}
        }
      }

      const duration = Date.now() - startTimeRef.current
      const isError = finalOutput.startsWith('Error:')
      const status: 'success' | 'error' = isError ? 'error' : 'success'
      setHistory(prev => [{
        id: `${Date.now()}`,
        agent: selectedAgent || 'No Agent',
        prompt: prompt.trim(),
        output: finalOutput,
        duration,
        status,
        timestamp: new Date(),
      }, ...prev].slice(0, 20))

    } catch (err: unknown) {
      if (err instanceof Error && err.name === 'AbortError') {
        setOutput('Test cancelled.')
      } else {
        setOutput(`Error: ${String(err)}`)
      }
    } finally {
      setRunning(false)
      abortRef.current = null
    }
  }, [prompt, selectedAgent])

  const cancelRun = () => { abortRef.current?.abort() }

  const copyOutput = () => {
    navigator.clipboard.writeText(output)
    toast('success', 'Copied to clipboard')
  }

  const loadFromHistory = (item: TestResult) => {
    setSelectedAgent(item.agent === 'No Agent' ? '' : item.agent)
    setPrompt(item.prompt)
    setOutput(item.output)
  }

  const clearAll = () => {
    setOutput('')
    setPrompt('')
    setSelectedAgent('')
  }

  return (
    <div className="h-screen flex flex-col">
      {/* Header */}
      <div className="px-6 py-4 border-b border-border bg-surface shrink-0">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-lg font-semibold flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-accent" />
              Agent Playground
            </h1>
            <p className="text-xs text-text-muted mt-0.5">Test any agent with a prompt. See the output. Iterate and improve.</p>
          </div>
          <div className="flex items-center gap-2">
            <button
              onClick={clearAll}
              className="flex items-center gap-2 px-3 py-1.5 text-sm rounded-lg border border-border hover:bg-surface-2 transition-colors"
            >
              <Trash2 className="w-3.5 h-3.5" />
              Clear
            </button>
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className="flex-1 flex min-h-0">
        {/* Left: Input */}
        <div className="w-1/2 flex flex-col border-r border-border">
          {/* Agent Picker */}
          <div className="px-5 py-3 border-b border-border shrink-0">
            <label className="text-xs font-medium text-text-muted block mb-1.5">Agent</label>
            <div className="relative">
              <button
                onClick={() => setShowAgentPicker(!showAgentPicker)}
                className="w-full flex items-center justify-between px-3 py-2.5 rounded-xl bg-surface-2 border border-border text-sm text-text hover:border-accent/40 transition-colors"
              >
                <span className="flex items-center gap-2">
                  {currentAgent ? (
                    <>
                      <AgentIcon
                        name={currentAgent.name}
                        uid={`pg-${currentAgent.name}`}
                        size={20}
                        global
                      />
                      <span className="font-medium">{currentAgent.name}</span>
                    </>
                  ) : (
                    <span className="text-text-muted">No agent (raw prompt)</span>
                  )}
                </span>
                <ChevronDown className="w-4 h-4 text-text-muted" />
              </button>

              {showAgentPicker && (
                <div className="absolute top-full left-0 right-0 mt-1 bg-surface border border-border rounded-xl shadow-2xl z-20 max-h-[300px] overflow-y-auto">
                  <div className="p-2 border-b border-border">
                    <input
                      value={agentFilter}
                      onChange={e => setAgentFilter(e.target.value)}
                      placeholder="Search agents..."
                      className="w-full bg-surface-2 border border-border rounded-lg px-3 py-2 text-sm text-text focus:outline-none focus:border-accent/50"
                      autoFocus
                    />
                  </div>
                  <button
                    onClick={() => { setSelectedAgent(''); setShowAgentPicker(false); setAgentFilter('') }}
                    className={`w-full flex items-center gap-2 px-3 py-2.5 text-sm hover:bg-surface-2 transition-colors ${!selectedAgent ? 'bg-accent-muted text-accent' : 'text-text-secondary'}`}
                  >
                    <span className="w-5 h-5 rounded-md bg-surface-3 flex items-center justify-center text-[10px]">—</span>
                    No Agent (raw prompt)
                  </button>
                  {filteredAgents.map(agent => (
                    <button
                      key={agent.name}
                      onClick={() => { setSelectedAgent(agent.filename || agent.name); setShowAgentPicker(false); setAgentFilter('') }}
                      className={`w-full flex items-center gap-2 px-3 py-2.5 text-sm hover:bg-surface-2 transition-colors ${selectedAgent === agent.name || selectedAgent === agent.filename ? 'bg-accent-muted text-accent' : ''}`}
                    >
                      <AgentIcon name={agent.name} uid={`pick-${agent.name}`} size={20} global />
                      <div className="text-left min-w-0">
                        <p className="font-medium truncate">{agent.name}</p>
                        <p className="text-[10px] text-text-muted truncate">{agent.description?.slice(0, 60)}</p>
                      </div>
                    </button>
                  ))}
                </div>
              )}
            </div>
          </div>

          {/* Prompt Input */}
          <div className="flex-1 flex flex-col px-5 py-4">
            <label className="text-xs font-medium text-text-muted mb-1.5">Test Prompt</label>
            <textarea
              value={prompt}
              onChange={e => setPrompt(e.target.value)}
              placeholder={selectedAgent
                ? `Test "${currentAgent?.name || selectedAgent}" with a prompt...\n\ne.g. Write a Shopify App Store listing for Pinzo`
                : 'Enter a raw prompt to test without any agent...'
              }
              className="flex-1 bg-surface-2 border border-border rounded-xl px-4 py-3 text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors placeholder:text-text-muted font-mono"
              onKeyDown={e => { if (e.key === 'Enter' && e.metaKey) { e.preventDefault(); runTest() } }}
            />
            <div className="flex items-center justify-between mt-3">
              <p className="text-[10px] text-text-muted">
                {prompt.length > 0 && `${prompt.length} chars`}
                {prompt.length > 0 && ' · '}
                <kbd className="px-1 py-0.5 rounded bg-surface-2 border border-border text-[9px] font-mono">Cmd+Enter</kbd> to run
              </p>
              <div className="flex gap-2">
                {running && (
                  <button
                    onClick={cancelRun}
                    className="px-3 py-2 border border-red/40 text-red rounded-xl text-sm font-medium hover:bg-red-muted transition-colors"
                  >
                    Cancel
                  </button>
                )}
                <button
                  onClick={runTest}
                  disabled={!prompt.trim() || running}
                  className="flex items-center gap-2 px-5 py-2 bg-accent text-white rounded-xl text-sm font-medium hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                >
                  {running ? <><Loader className="w-4 h-4 animate-spin" /> Running...</> : <><Play className="w-4 h-4" /> Run Test</>}
                </button>
              </div>
            </div>
          </div>

          {/* History */}
          {history.length > 0 && (
            <div className="border-t border-border px-5 py-3 shrink-0 max-h-[200px] overflow-y-auto">
              <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted mb-2 flex items-center gap-1.5">
                <Clock className="w-3 h-3" /> Recent Tests ({history.length})
              </p>
              <div className="space-y-1">
                {history.map(item => (
                  <button
                    key={item.id}
                    onClick={() => loadFromHistory(item)}
                    className="w-full flex items-center gap-2 px-2.5 py-2 rounded-lg hover:bg-surface-2 transition-colors text-left"
                  >
                    {item.status === 'success'
                      ? <CheckCircle className="w-3 h-3 text-green shrink-0" />
                      : <AlertCircle className="w-3 h-3 text-red shrink-0" />
                    }
                    <div className="min-w-0 flex-1">
                      <p className="text-[11px] font-medium truncate">{item.agent}</p>
                      <p className="text-[10px] text-text-muted truncate">{item.prompt}</p>
                    </div>
                    <span className="text-[10px] text-text-muted shrink-0">
                      {(item.duration / 1000).toFixed(1)}s
                    </span>
                  </button>
                ))}
              </div>
            </div>
          )}
        </div>

        {/* Right: Output */}
        <div className="w-1/2 flex flex-col">
          <div className="flex items-center justify-between px-5 py-3 border-b border-border shrink-0">
            <p className="text-xs font-medium text-text-muted flex items-center gap-1.5">
              {running ? (
                <><Loader className="w-3 h-3 animate-spin text-purple" /> Generating...</>
              ) : output ? (
                <><CheckCircle className="w-3 h-3 text-green" /> Output</>
              ) : (
                'Output'
              )}
            </p>
            <div className="flex items-center gap-2">
              {output && !running && (
                <>
                  <button
                    onClick={runTest}
                    className="flex items-center gap-1.5 text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                  >
                    <RotateCcw className="w-3 h-3" /> Re-run
                  </button>
                  <button
                    onClick={copyOutput}
                    className="flex items-center gap-1.5 text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                  >
                    <Copy className="w-3 h-3" /> Copy
                  </button>
                </>
              )}
            </div>
          </div>

          <div className="flex-1 overflow-y-auto p-5">
            {output ? (
              <pre
                ref={outputRef}
                className="text-sm text-text whitespace-pre-wrap leading-relaxed font-mono"
              >
                {output}
              </pre>
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-center">
                <div className="w-14 h-14 rounded-2xl bg-purple-muted flex items-center justify-center mb-3">
                  <Play className="w-6 h-6 text-purple" />
                </div>
                <p className="text-sm font-medium text-text-secondary mb-1">No output yet</p>
                <p className="text-xs text-text-muted max-w-[260px]">
                  Select an agent, write a test prompt, and click Run Test to see the output here.
                </p>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  )
}

import { useState, useCallback, useRef, useEffect, useMemo } from 'react'
import {
  Play, Copy, Trash2, Loader, CheckCircle, AlertCircle, Square,
  ChevronDown, RotateCcw, Clock, Sparkles, Download, Search,
  Settings2, X, ArrowDown, Terminal,
} from 'lucide-react'
import { getUnifiedAgents } from '../lib/api'
import { useApi } from '../hooks/useApi'
import { toast } from '../components/Toast'
import AgentIcon from '../components/AgentIcon'
import { MarkdownRenderer } from '../components/MarkdownRenderer'

// ─── Types ──────────────────────────────────────────────────────────────────

interface TestResult {
  id: string
  agent: string
  agentName: string
  prompt: string
  output: string
  duration: number
  status: 'success' | 'error'
  timestamp: Date
}

interface PlaygroundSettings {
  timeoutMs: number
  customInstructions: string
  outputMode: 'markdown' | 'raw'
}

const STORAGE_KEY = 'claude-hub:playground-history'
const SETTINGS_KEY = 'claude-hub:playground-settings'

const DEFAULT_SETTINGS: PlaygroundSettings = {
  timeoutMs: 120000,
  customInstructions: '',
  outputMode: 'markdown',
}

// ─── Helpers ────────────────────────────────────────────────────────────────

function loadPersistedHistory(): TestResult[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return []
    const parsed = JSON.parse(raw)
    return parsed.map((r: TestResult) => ({ ...r, timestamp: new Date(r.timestamp) }))
  } catch { return [] }
}

function loadPersistedSettings(): PlaygroundSettings {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY)
    if (!raw) return DEFAULT_SETTINGS
    return { ...DEFAULT_SETTINGS, ...JSON.parse(raw) }
  } catch { return DEFAULT_SETTINGS }
}

function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`
  const min = Math.floor(ms / 60000)
  const sec = ((ms % 60000) / 1000).toFixed(0)
  return `${min}m ${sec}s`
}

function formatTime(date: Date): string {
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

// ─── Component ──────────────────────────────────────────────────────────────

export default function Playground() {
  const { data: agents } = useApi(getUnifiedAgents)

  // Core state
  const [selectedAgent, setSelectedAgent] = useState<string>('')
  const [prompt, setPrompt] = useState('')
  const [running, setRunning] = useState(false)
  const [output, setOutput] = useState('')
  const [history, setHistory] = useState<TestResult[]>(loadPersistedHistory)
  const [settings, setSettings] = useState<PlaygroundSettings>(loadPersistedSettings)

  // UI state
  const [showAgentPicker, setShowAgentPicker] = useState(false)
  const [agentFilter, setAgentFilter] = useState('')
  const [showSettings, setShowSettings] = useState(false)
  const [historyFilter, setHistoryFilter] = useState('')
  const [elapsedMs, setElapsedMs] = useState(0)
  const [showScrollBottom, setShowScrollBottom] = useState(false)

  // Refs
  const outputRef = useRef<HTMLDivElement>(null)
  const abortRef = useRef<AbortController | null>(null)
  const startTimeRef = useRef<number>(0)
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const agentPickerRef = useRef<HTMLDivElement>(null)

  // ─── Computed ───────────────────────────────────────────────────────────

  const allAgents = agents || []
  const globalAgents = allAgents.filter(a => a.scope === 'global')
  const projectAgents = allAgents.filter(a => a.scope === 'project')

  const filteredAgents = useMemo(() => {
    const q = agentFilter.toLowerCase()
    return allAgents.filter(a =>
      a.name.toLowerCase().includes(q) ||
      a.filename?.toLowerCase().includes(q) ||
      a.description?.toLowerCase().includes(q)
    )
  }, [allAgents, agentFilter])

  const filteredGlobal = filteredAgents.filter(a => a.scope === 'global')
  const filteredProject = filteredAgents.filter(a => a.scope === 'project')

  const currentAgent = allAgents.find(a =>
    a.filename === selectedAgent || a.name === selectedAgent
  )

  const filteredHistory = useMemo(() => {
    if (!historyFilter.trim()) return history
    const q = historyFilter.toLowerCase()
    return history.filter(h =>
      h.agentName.toLowerCase().includes(q) ||
      h.prompt.toLowerCase().includes(q)
    )
  }, [history, historyFilter])

  // ─── Persist history ──────────────────────────────────────────────────

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(history.slice(0, 50)))
  }, [history])

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings))
  }, [settings])

  // ─── Auto-scroll output ──────────────────────────────────────────────

  useEffect(() => {
    if (running && outputRef.current) {
      outputRef.current.scrollTo({ top: outputRef.current.scrollHeight, behavior: 'smooth' })
    }
  }, [output, running])

  // ─── Scroll detection ────────────────────────────────────────────────

  useEffect(() => {
    const el = outputRef.current
    if (!el) return
    const handleScroll = () => {
      setShowScrollBottom(el.scrollHeight - el.scrollTop - el.clientHeight > 100)
    }
    el.addEventListener('scroll', handleScroll)
    return () => el.removeEventListener('scroll', handleScroll)
  }, [output])

  // ─── Click outside agent picker ───────────────────────────────────────

  useEffect(() => {
    if (!showAgentPicker) return
    const handler = (e: MouseEvent) => {
      if (agentPickerRef.current && !agentPickerRef.current.contains(e.target as Node)) {
        setShowAgentPicker(false)
        setAgentFilter('')
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [showAgentPicker])

  // ─── Elapsed timer ────────────────────────────────────────────────────

  useEffect(() => {
    if (running) {
      timerRef.current = setInterval(() => {
        setElapsedMs(Date.now() - startTimeRef.current)
      }, 100)
    } else {
      if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null }
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current) }
  }, [running])

  // ─── Run test ─────────────────────────────────────────────────────────

  const runTest = useCallback(async (overridePrompt?: string, overrideAgent?: string) => {
    const testPrompt = (overridePrompt ?? prompt).trim()
    if (!testPrompt) { toast('error', 'Enter a test prompt'); return }

    const agentToUse = overrideAgent ?? selectedAgent
    setRunning(true)
    setOutput('')
    setElapsedMs(0)
    startTimeRef.current = Date.now()
    abortRef.current = new AbortController()

    try {
      const body: Record<string, unknown> = {
        agentName: agentToUse || undefined,
        prompt: testPrompt,
        timeoutMs: settings.timeoutMs,
      }
      if (settings.customInstructions.trim()) {
        body.customInstructions = settings.customInstructions.trim()
      }

      const response = await fetch('/api/playground/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
        signal: abortRef.current.signal,
      })

      if (!response.body) throw new Error('No response body')
      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''
      let fullOutput = ''
      let hadError = false

      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        buffer += decoder.decode(value, { stream: true })
        const parts = buffer.split('\n')
        buffer = parts.pop() ?? ''

        for (const line of parts) {
          const trimmed = line.trim()
          if (!trimmed.startsWith('data: ')) continue
          try {
            const event = JSON.parse(trimmed.slice(6))
            if (event.type === 'chunk') {
              fullOutput += event.content
              setOutput(fullOutput)
            } else if (event.type === 'done') {
              fullOutput = event.output || fullOutput
              setOutput(fullOutput)
            } else if (event.type === 'error') {
              fullOutput = `Error: ${event.error}`
              setOutput(fullOutput)
              hadError = true
            }
          } catch {}
        }
      }

      // Flush remaining buffer
      if (buffer.trim()) {
        for (const line of buffer.split('\n')) {
          const trimmed = line.trim()
          if (!trimmed.startsWith('data: ')) continue
          try {
            const event = JSON.parse(trimmed.slice(6))
            if (event.type === 'chunk') {
              fullOutput += event.content
              setOutput(fullOutput)
            } else if (event.type === 'done') {
              fullOutput = event.output || fullOutput
              setOutput(fullOutput)
            } else if (event.type === 'error') {
              fullOutput = `Error: ${event.error}`
              setOutput(fullOutput)
              hadError = true
            }
          } catch {}
        }
      }

      const duration = Date.now() - startTimeRef.current
      const agentDisplay = currentAgent?.name || agentToUse || 'No Agent'

      setHistory(prev => [{
        id: `${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        agent: agentToUse || '',
        agentName: agentDisplay,
        prompt: testPrompt,
        output: fullOutput,
        duration,
        status: hadError ? 'error' : 'success',
        timestamp: new Date(),
      }, ...prev].slice(0, 50))

    } catch (err: unknown) {
      const duration = Date.now() - startTimeRef.current
      if (err instanceof Error && err.name === 'AbortError') {
        setOutput(prev => prev ? prev + '\n\n---\n*Test cancelled by user*' : 'Test cancelled.')
      } else {
        const errMsg = err instanceof Error ? err.message : String(err)
        setOutput(`Error: ${errMsg}`)
        const agentDisplay = currentAgent?.name || agentToUse || 'No Agent'
        setHistory(prev => [{
          id: `${Date.now()}`,
          agent: agentToUse || '',
          agentName: agentDisplay,
          prompt: testPrompt,
          output: `Error: ${errMsg}`,
          duration,
          status: 'error',
          timestamp: new Date(),
        }, ...prev].slice(0, 50))
      }
    } finally {
      setRunning(false)
      abortRef.current = null
    }
  }, [prompt, selectedAgent, settings, currentAgent])

  const cancelRun = () => { abortRef.current?.abort() }

  // ─── Actions ──────────────────────────────────────────────────────────

  const copyOutput = () => {
    navigator.clipboard.writeText(output)
    toast('success', 'Copied to clipboard')
  }

  const exportOutput = () => {
    if (!output) return
    const name = currentAgent?.name || 'raw-prompt'
    const blob = new Blob([`# Playground Test: ${name}\n\n**Prompt:**\n${prompt}\n\n**Output:**\n${output}`], { type: 'text/markdown' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `playground-${name.toLowerCase().replace(/\s+/g, '-')}-${Date.now()}.md`
    a.click()
    URL.revokeObjectURL(url)
  }

  const loadFromHistory = (item: TestResult) => {
    setSelectedAgent(item.agent)
    setPrompt(item.prompt)
    setOutput(item.output)
  }

  const rerunFromHistory = (item: TestResult) => {
    setSelectedAgent(item.agent)
    setPrompt(item.prompt)
    runTest(item.prompt, item.agent)
  }

  const removeHistoryItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation()
    setHistory(prev => prev.filter(h => h.id !== id))
  }

  const clearHistory = () => {
    setHistory([])
    localStorage.removeItem(STORAGE_KEY)
  }

  const clearAll = () => {
    setOutput('')
    setPrompt('')
    setSelectedAgent('')
  }

  // ─── Keyboard ─────────────────────────────────────────────────────────

  const handlePromptKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      e.preventDefault()
      runTest()
    }
  }

  // ─── Stats ────────────────────────────────────────────────────────────

  const successCount = history.filter(h => h.status === 'success').length
  const errorCount = history.filter(h => h.status === 'error').length
  const avgDuration = history.length > 0
    ? history.reduce((sum, h) => sum + h.duration, 0) / history.length
    : 0

  // ─── Render ───────────────────────────────────────────────────────────

  return (
    <div className="h-screen flex flex-col">
      {/* Header */}
      <div className="px-6 py-3.5 border-b border-border bg-surface shrink-0">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-lg font-semibold flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-accent" />
              Agent Playground
            </h1>
            <p className="text-[11px] text-text-muted mt-0.5">
              Test any agent with a prompt. Real-time streaming output.
              {history.length > 0 && (
                <span className="ml-2 text-text-secondary">
                  {successCount} passed · {errorCount} failed · avg {formatDuration(avgDuration)}
                </span>
              )}
            </p>
          </div>
          <div className="flex items-center gap-1.5">
            <button
              onClick={() => setShowSettings(!showSettings)}
              title="Settings"
              className={`p-2 rounded-lg transition-colors ${showSettings ? 'bg-accent-muted text-accent' : 'text-text-muted hover:text-text hover:bg-surface-2'}`}
            >
              <Settings2 className="w-4 h-4" />
            </button>
            <button
              onClick={clearAll}
              title="Clear editor"
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-lg border border-border hover:bg-surface-2 transition-colors text-text-muted hover:text-text"
            >
              <Trash2 className="w-3.5 h-3.5" />
              Clear
            </button>
          </div>
        </div>

        {/* Settings Panel */}
        {showSettings && (
          <div className="mt-3 p-4 bg-surface-2 rounded-xl border border-border space-y-3">
            <div className="flex items-center justify-between">
              <p className="text-xs font-semibold text-text">Settings</p>
              <button onClick={() => setShowSettings(false)} className="p-1 text-text-muted hover:text-text">
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[11px] font-medium text-text-muted block mb-1">Timeout</label>
                <select
                  value={settings.timeoutMs}
                  onChange={e => setSettings(s => ({ ...s, timeoutMs: Number(e.target.value) }))}
                  className="w-full bg-surface border border-border rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-accent/50"
                >
                  <option value={30000}>30 seconds</option>
                  <option value={60000}>1 minute</option>
                  <option value={120000}>2 minutes</option>
                  <option value={300000}>5 minutes</option>
                  <option value={600000}>10 minutes</option>
                </select>
              </div>
              <div>
                <label className="text-[11px] font-medium text-text-muted block mb-1">Output format</label>
                <select
                  value={settings.outputMode}
                  onChange={e => setSettings(s => ({ ...s, outputMode: e.target.value as 'markdown' | 'raw' }))}
                  className="w-full bg-surface border border-border rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-accent/50"
                >
                  <option value="markdown">Markdown (rendered)</option>
                  <option value="raw">Raw text</option>
                </select>
              </div>
            </div>
            <div>
              <label className="text-[11px] font-medium text-text-muted block mb-1">
                Custom instructions override
                <span className="font-normal text-text-muted/70 ml-1">(replaces agent system prompt if set)</span>
              </label>
              <textarea
                value={settings.customInstructions}
                onChange={e => setSettings(s => ({ ...s, customInstructions: e.target.value }))}
                placeholder="Leave empty to use agent's default instructions..."
                className="w-full bg-surface border border-border rounded-lg px-3 py-2 text-xs font-mono resize-none focus:outline-none focus:border-accent/50 h-20"
              />
            </div>
          </div>
        )}
      </div>

      {/* Main Content */}
      <div className="flex-1 flex min-h-0">
        {/* Left: Input + History */}
        <div className="w-1/2 flex flex-col border-r border-border min-w-0">
          {/* Agent Picker */}
          <div className="px-5 py-3 border-b border-border shrink-0">
            <label className="text-[11px] font-medium text-text-muted block mb-1.5">Agent</label>
            <div className="relative" ref={agentPickerRef}>
              <button
                onClick={() => { setShowAgentPicker(!showAgentPicker); setAgentFilter('') }}
                className="w-full flex items-center justify-between px-3 py-2.5 rounded-xl bg-surface-2 border border-border text-sm text-text hover:border-accent/40 transition-colors"
              >
                <span className="flex items-center gap-2 min-w-0">
                  {currentAgent ? (
                    <>
                      <AgentIcon name={currentAgent.name} uid={`pg-${currentAgent.name}`} size={20} global={currentAgent.scope === 'global'} />
                      <span className="font-medium truncate">{currentAgent.name}</span>
                      <span className="text-[10px] text-text-muted shrink-0">({currentAgent.model})</span>
                    </>
                  ) : (
                    <span className="text-text-muted">No agent (raw prompt)</span>
                  )}
                </span>
                <ChevronDown className={`w-4 h-4 text-text-muted shrink-0 transition-transform ${showAgentPicker ? 'rotate-180' : ''}`} />
              </button>

              {showAgentPicker && (
                <div className="absolute top-full left-0 right-0 mt-1 bg-surface border border-border rounded-xl shadow-2xl z-20 max-h-[350px] flex flex-col overflow-hidden">
                  <div className="p-2 border-b border-border shrink-0">
                    <div className="relative">
                      <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-text-muted" />
                      <input
                        value={agentFilter}
                        onChange={e => setAgentFilter(e.target.value)}
                        placeholder="Search agents..."
                        className="w-full bg-surface-2 border border-border rounded-lg pl-8 pr-3 py-2 text-sm text-text focus:outline-none focus:border-accent/50"
                        autoFocus
                      />
                    </div>
                  </div>
                  <div className="overflow-y-auto flex-1">
                    {/* No Agent option */}
                    <button
                      onClick={() => { setSelectedAgent(''); setShowAgentPicker(false); setAgentFilter('') }}
                      className={`w-full flex items-center gap-2 px-3 py-2.5 text-sm hover:bg-surface-2 transition-colors ${!selectedAgent ? 'bg-accent-muted text-accent' : 'text-text-secondary'}`}
                    >
                      <span className="w-5 h-5 rounded-md bg-surface-3 flex items-center justify-center text-[10px] shrink-0">—</span>
                      <span>No Agent (raw prompt)</span>
                    </button>

                    {/* Global agents */}
                    {filteredGlobal.length > 0 && (
                      <>
                        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted px-3 pt-2 pb-1">
                          Global ({filteredGlobal.length})
                        </p>
                        {filteredGlobal.map(agent => (
                          <button
                            key={`g-${agent.filename}`}
                            onClick={() => { setSelectedAgent(agent.filename || agent.name); setShowAgentPicker(false); setAgentFilter('') }}
                            className={`w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-surface-2 transition-colors ${selectedAgent === agent.filename || selectedAgent === agent.name ? 'bg-accent-muted text-accent' : ''}`}
                          >
                            <AgentIcon name={agent.name} uid={`pick-g-${agent.name}`} size={20} global />
                            <div className="text-left min-w-0 flex-1">
                              <p className="font-medium truncate text-[12px]">{agent.name}</p>
                              <p className="text-[10px] text-text-muted truncate">{agent.description?.slice(0, 60)}</p>
                            </div>
                            <span className="text-[9px] text-text-muted shrink-0 font-mono">{agent.model}</span>
                          </button>
                        ))}
                      </>
                    )}

                    {/* Project agents */}
                    {filteredProject.length > 0 && (
                      <>
                        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted px-3 pt-2 pb-1">
                          Project ({filteredProject.length})
                        </p>
                        {filteredProject.map(agent => (
                          <button
                            key={`p-${agent.filename}-${agent.projectName}`}
                            onClick={() => { setSelectedAgent(agent.filename || agent.name); setShowAgentPicker(false); setAgentFilter('') }}
                            className={`w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-surface-2 transition-colors ${selectedAgent === agent.filename || selectedAgent === agent.name ? 'bg-accent-muted text-accent' : ''}`}
                          >
                            <AgentIcon name={agent.name} uid={`pick-p-${agent.name}`} size={20} global={false} />
                            <div className="text-left min-w-0 flex-1">
                              <p className="font-medium truncate text-[12px]">{agent.name}</p>
                              <p className="text-[10px] text-text-muted truncate">{agent.projectName}</p>
                            </div>
                            <span className="text-[9px] text-text-muted shrink-0 font-mono">{agent.model}</span>
                          </button>
                        ))}
                      </>
                    )}

                    {filteredAgents.length === 0 && agentFilter && (
                      <p className="text-xs text-text-muted text-center py-4">No agents match "{agentFilter}"</p>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Agent description */}
            {currentAgent?.description && (
              <p className="text-[11px] text-text-muted mt-1.5 px-0.5 line-clamp-2">{currentAgent.description}</p>
            )}
          </div>

          {/* Prompt Input */}
          <div className="flex-1 flex flex-col px-5 py-3 min-h-0">
            <label className="text-[11px] font-medium text-text-muted mb-1.5">Test Prompt</label>
            <textarea
              value={prompt}
              onChange={e => setPrompt(e.target.value)}
              placeholder={currentAgent
                ? `Test "${currentAgent.name}" with a prompt...\n\ne.g. Write a Shopify App Store listing for Pinzo`
                : 'Enter a raw prompt to test without any agent...'
              }
              className="flex-1 bg-surface-2 border border-border rounded-xl px-4 py-3 text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors placeholder:text-text-muted font-mono min-h-[120px]"
              onKeyDown={handlePromptKeyDown}
            />
            <div className="flex items-center justify-between mt-2.5">
              <p className="text-[10px] text-text-muted">
                {prompt.length > 0 && <span className="text-text-secondary">{prompt.length} chars</span>}
                {prompt.length > 0 && ' · '}
                <kbd className="px-1 py-0.5 rounded bg-surface-2 border border-border text-[9px] font-mono">⌘Enter</kbd> to run
                {settings.customInstructions && (
                  <span className="ml-2 text-amber">· custom instructions active</span>
                )}
              </p>
              <div className="flex gap-2">
                {running ? (
                  <button
                    onClick={cancelRun}
                    className="flex items-center gap-1.5 px-3 py-2 bg-red/90 text-white rounded-xl text-xs font-medium hover:bg-red transition-colors"
                  >
                    <Square className="w-3 h-3 fill-current" />
                    Stop ({formatDuration(elapsedMs)})
                  </button>
                ) : (
                  <button
                    onClick={() => runTest()}
                    disabled={!prompt.trim()}
                    className="flex items-center gap-2 px-5 py-2 bg-accent text-white rounded-xl text-sm font-medium hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                  >
                    <Play className="w-4 h-4" /> Run Test
                  </button>
                )}
              </div>
            </div>
          </div>

          {/* History */}
          <div className="border-t border-border shrink-0 max-h-[240px] flex flex-col">
            <div className="px-5 py-2 flex items-center justify-between shrink-0">
              <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted flex items-center gap-1.5">
                <Clock className="w-3 h-3" />
                History ({history.length})
              </p>
              <div className="flex items-center gap-1.5">
                {history.length > 3 && (
                  <div className="relative">
                    <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-text-muted" />
                    <input
                      value={historyFilter}
                      onChange={e => setHistoryFilter(e.target.value)}
                      placeholder="Filter..."
                      className="w-28 bg-surface-2 border border-border rounded-md pl-6 pr-2 py-1 text-[10px] focus:outline-none focus:border-accent/50"
                    />
                  </div>
                )}
                {history.length > 0 && (
                  <button
                    onClick={clearHistory}
                    className="text-[10px] text-text-muted hover:text-red transition-colors px-1"
                    title="Clear all history"
                  >
                    Clear all
                  </button>
                )}
              </div>
            </div>
            <div className="flex-1 overflow-y-auto px-4 pb-2">
              {filteredHistory.length === 0 ? (
                <p className="text-[11px] text-text-muted text-center py-3">
                  {history.length === 0 ? 'No tests run yet.' : 'No matches.'}
                </p>
              ) : (
                <div className="space-y-0.5">
                  {filteredHistory.map(item => (
                    <div
                      key={item.id}
                      onClick={() => loadFromHistory(item)}
                      className="group flex items-center gap-2 px-2.5 py-2 rounded-lg hover:bg-surface-2 transition-colors cursor-pointer"
                    >
                      {item.status === 'success'
                        ? <CheckCircle className="w-3.5 h-3.5 text-green shrink-0" />
                        : <AlertCircle className="w-3.5 h-3.5 text-red shrink-0" />
                      }
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-1.5">
                          <p className="text-[11px] font-medium truncate">{item.agentName}</p>
                          <span className="text-[9px] text-text-muted">{formatTime(item.timestamp)}</span>
                        </div>
                        <p className="text-[10px] text-text-muted truncate">{item.prompt}</p>
                      </div>
                      <div className="flex items-center gap-1 shrink-0">
                        <span className="text-[10px] text-text-muted">{formatDuration(item.duration)}</span>
                        <button
                          onClick={(e) => { e.stopPropagation(); rerunFromHistory(item) }}
                          className="p-1 rounded opacity-0 group-hover:opacity-100 text-text-muted hover:text-accent transition-all"
                          title="Re-run this test"
                        >
                          <RotateCcw className="w-3 h-3" />
                        </button>
                        <button
                          onClick={(e) => removeHistoryItem(e, item.id)}
                          className="p-1 rounded opacity-0 group-hover:opacity-100 text-text-muted hover:text-red transition-all"
                          title="Remove from history"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Right: Output */}
        <div className="w-1/2 flex flex-col min-w-0 relative">
          {/* Output header */}
          <div className="flex items-center justify-between px-5 py-2.5 border-b border-border shrink-0">
            <p className="text-xs font-medium text-text-muted flex items-center gap-1.5">
              {running ? (
                <>
                  <Loader className="w-3.5 h-3.5 animate-spin text-purple" />
                  <span>Streaming... <span className="text-text-secondary font-mono">{formatDuration(elapsedMs)}</span></span>
                </>
              ) : output ? (
                <>
                  {output.startsWith('Error:') ? (
                    <><AlertCircle className="w-3.5 h-3.5 text-red" /> Error</>
                  ) : (
                    <><CheckCircle className="w-3.5 h-3.5 text-green" /> Output</>
                  )}
                  {history[0] && (
                    <span className="text-text-muted font-mono ml-1">({formatDuration(history[0].duration)})</span>
                  )}
                </>
              ) : (
                <><Terminal className="w-3.5 h-3.5" /> Output</>
              )}
            </p>
            <div className="flex items-center gap-1">
              {output && !running && (
                <>
                  <button
                    onClick={() => runTest()}
                    disabled={!prompt.trim()}
                    className="flex items-center gap-1 text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                    title="Re-run test"
                  >
                    <RotateCcw className="w-3 h-3" /> Re-run
                  </button>
                  <button
                    onClick={copyOutput}
                    className="flex items-center gap-1 text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                    title="Copy output"
                  >
                    <Copy className="w-3 h-3" /> Copy
                  </button>
                  <button
                    onClick={exportOutput}
                    className="flex items-center gap-1 text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                    title="Export as Markdown"
                  >
                    <Download className="w-3 h-3" /> Export
                  </button>
                  <button
                    onClick={() => setSettings(s => ({ ...s, outputMode: s.outputMode === 'markdown' ? 'raw' : 'markdown' }))}
                    className="text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                    title="Toggle output format"
                  >
                    {settings.outputMode === 'markdown' ? 'Raw' : 'Rendered'}
                  </button>
                </>
              )}
            </div>
          </div>

          {/* Output content */}
          <div ref={outputRef} className="flex-1 overflow-y-auto p-5">
            {output ? (
              settings.outputMode === 'markdown' ? (
                <div className="text-sm leading-relaxed">
                  <MarkdownRenderer content={output} />
                  {running && (
                    <span className="inline-block w-0.5 h-4 bg-purple animate-pulse ml-0.5 align-middle rounded-full" />
                  )}
                </div>
              ) : (
                <pre className="text-sm text-text whitespace-pre-wrap leading-relaxed font-mono break-words">
                  {output}
                  {running && (
                    <span className="inline-block w-0.5 h-4 bg-purple animate-pulse ml-0.5 align-middle rounded-full" />
                  )}
                </pre>
              )
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-center">
                <div className="w-14 h-14 rounded-2xl bg-purple-muted flex items-center justify-center mb-3">
                  <Play className="w-6 h-6 text-purple" />
                </div>
                <p className="text-sm font-medium text-text-secondary mb-1">No output yet</p>
                <p className="text-xs text-text-muted max-w-[280px]">
                  Select an agent, write a test prompt, and click Run Test to see real-time streaming output.
                </p>
              </div>
            )}
          </div>

          {/* Scroll to bottom */}
          {showScrollBottom && output && (
            <div className="absolute bottom-4 right-4">
              <button
                onClick={() => outputRef.current?.scrollTo({ top: outputRef.current.scrollHeight, behavior: 'smooth' })}
                className="p-2 rounded-full bg-surface border border-border shadow-lg hover:bg-surface-2 transition-all text-text-muted hover:text-text"
              >
                <ArrowDown className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

import { useState, useCallback, useRef, useEffect, useMemo } from 'react'
import {
  Play, Copy, Trash2, Loader, CheckCircle, AlertCircle, Square,
  ChevronDown, RotateCcw, Clock, Sparkles, Download, Search,
  Settings2, X, ArrowDown, Terminal,
} from 'lucide-react'
import { getUnifiedAgents } from '../lib/api'
import { useApi } from '../hooks/useApi'
import { toast } from '../components/Toast'
import AgentIcon from '../components/AgentIcon'
import { MarkdownRenderer } from '../components/MarkdownRenderer'

// ─── Types ──────────────────────────────────────────────────────────────────

interface TestResult {
  id: string
  agent: string
  agentName: string
  prompt: string
  output: string
  duration: number
  status: 'success' | 'error'
  timestamp: Date
}

interface PlaygroundSettings {
  timeoutMs: number
  customInstructions: string
  outputMode: 'markdown' | 'raw'
}

const STORAGE_KEY = 'claude-hub:playground-history'
const SETTINGS_KEY = 'claude-hub:playground-settings'

const DEFAULT_SETTINGS: PlaygroundSettings = {
  timeoutMs: 120000,
  customInstructions: '',
  outputMode: 'markdown',
}

// ─── Helpers ────────────────────────────────────────────────────────────────

function loadPersistedHistory(): TestResult[] {
  try {
    const raw = localStorage.getItem(STORAGE_KEY)
    if (!raw) return []
    const parsed = JSON.parse(raw)
    return parsed.map((r: TestResult) => ({ ...r, timestamp: new Date(r.timestamp) }))
  } catch { return [] }
}

function loadPersistedSettings(): PlaygroundSettings {
  try {
    const raw = localStorage.getItem(SETTINGS_KEY)
    if (!raw) return DEFAULT_SETTINGS
    return { ...DEFAULT_SETTINGS, ...JSON.parse(raw) }
  } catch { return DEFAULT_SETTINGS }
}

function formatDuration(ms: number): string {
  if (ms < 1000) return `${ms}ms`
  if (ms < 60000) return `${(ms / 1000).toFixed(1)}s`
  const min = Math.floor(ms / 60000)
  const sec = ((ms % 60000) / 1000).toFixed(0)
  return `${min}m ${sec}s`
}

function formatTime(date: Date): string {
  return date.toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })
}

// ─── Component ──────────────────────────────────────────────────────────────

export default function Playground() {
  const { data: agents } = useApi(getUnifiedAgents)

  // Core state
  const [selectedAgent, setSelectedAgent] = useState<string>('')
  const [prompt, setPrompt] = useState('')
  const [running, setRunning] = useState(false)
  const [output, setOutput] = useState('')
  const [history, setHistory] = useState<TestResult[]>(loadPersistedHistory)
  const [settings, setSettings] = useState<PlaygroundSettings>(loadPersistedSettings)

  // UI state
  const [showAgentPicker, setShowAgentPicker] = useState(false)
  const [agentFilter, setAgentFilter] = useState('')
  const [showSettings, setShowSettings] = useState(false)
  const [historyFilter, setHistoryFilter] = useState('')
  const [elapsedMs, setElapsedMs] = useState(0)
  const [showScrollBottom, setShowScrollBottom] = useState(false)

  // Refs
  const outputRef = useRef<HTMLDivElement>(null)
  const abortRef = useRef<AbortController | null>(null)
  const startTimeRef = useRef<number>(0)
  const timerRef = useRef<ReturnType<typeof setInterval> | null>(null)
  const agentPickerRef = useRef<HTMLDivElement>(null)

  // ─── Computed ───────────────────────────────────────────────────────────

  const allAgents = agents || []
  const globalAgents = allAgents.filter(a => a.scope === 'global')
  const projectAgents = allAgents.filter(a => a.scope === 'project')

  const filteredAgents = useMemo(() => {
    const q = agentFilter.toLowerCase()
    return allAgents.filter(a =>
      a.name.toLowerCase().includes(q) ||
      a.filename?.toLowerCase().includes(q) ||
      a.description?.toLowerCase().includes(q)
    )
  }, [allAgents, agentFilter])

  const filteredGlobal = filteredAgents.filter(a => a.scope === 'global')
  const filteredProject = filteredAgents.filter(a => a.scope === 'project')

  const currentAgent = allAgents.find(a =>
    a.filename === selectedAgent || a.name === selectedAgent
  )

  const filteredHistory = useMemo(() => {
    if (!historyFilter.trim()) return history
    const q = historyFilter.toLowerCase()
    return history.filter(h =>
      h.agentName.toLowerCase().includes(q) ||
      h.prompt.toLowerCase().includes(q)
    )
  }, [history, historyFilter])

  // ─── Persist history ──────────────────────────────────────────────────

  useEffect(() => {
    localStorage.setItem(STORAGE_KEY, JSON.stringify(history.slice(0, 50)))
  }, [history])

  useEffect(() => {
    localStorage.setItem(SETTINGS_KEY, JSON.stringify(settings))
  }, [settings])

  // ─── Auto-scroll output ──────────────────────────────────────────────

  useEffect(() => {
    if (running && outputRef.current) {
      outputRef.current.scrollTo({ top: outputRef.current.scrollHeight, behavior: 'smooth' })
    }
  }, [output, running])

  // ─── Scroll detection ────────────────────────────────────────────────

  useEffect(() => {
    const el = outputRef.current
    if (!el) return
    const handleScroll = () => {
      setShowScrollBottom(el.scrollHeight - el.scrollTop - el.clientHeight > 100)
    }
    el.addEventListener('scroll', handleScroll)
    return () => el.removeEventListener('scroll', handleScroll)
  }, [output])

  // ─── Click outside agent picker ───────────────────────────────────────

  useEffect(() => {
    if (!showAgentPicker) return
    const handler = (e: MouseEvent) => {
      if (agentPickerRef.current && !agentPickerRef.current.contains(e.target as Node)) {
        setShowAgentPicker(false)
        setAgentFilter('')
      }
    }
    document.addEventListener('mousedown', handler)
    return () => document.removeEventListener('mousedown', handler)
  }, [showAgentPicker])

  // ─── Elapsed timer ────────────────────────────────────────────────────

  useEffect(() => {
    if (running) {
      timerRef.current = setInterval(() => {
        setElapsedMs(Date.now() - startTimeRef.current)
      }, 100)
    } else {
      if (timerRef.current) { clearInterval(timerRef.current); timerRef.current = null }
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current) }
  }, [running])

  // ─── Run test ─────────────────────────────────────────────────────────

  const runTest = useCallback(async (overridePrompt?: string, overrideAgent?: string) => {
    const testPrompt = (overridePrompt ?? prompt).trim()
    if (!testPrompt) { toast('error', 'Enter a test prompt'); return }

    const agentToUse = overrideAgent ?? selectedAgent
    setRunning(true)
    setOutput('')
    setElapsedMs(0)
    startTimeRef.current = Date.now()
    abortRef.current = new AbortController()

    try {
      const body: Record<string, unknown> = {
        agentName: agentToUse || undefined,
        prompt: testPrompt,
        timeoutMs: settings.timeoutMs,
      }
      if (settings.customInstructions.trim()) {
        body.customInstructions = settings.customInstructions.trim()
      }

      const response = await fetch('/api/playground/run', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(body),
        signal: abortRef.current.signal,
      })

      if (!response.body) throw new Error('No response body')
      const reader = response.body.getReader()
      const decoder = new TextDecoder()
      let buffer = ''
      let fullOutput = ''
      let hadError = false

      while (true) {
        const { done, value } = await reader.read()
        if (done) break
        buffer += decoder.decode(value, { stream: true })
        const parts = buffer.split('\n')
        buffer = parts.pop() ?? ''

        for (const line of parts) {
          const trimmed = line.trim()
          if (!trimmed.startsWith('data: ')) continue
          try {
            const event = JSON.parse(trimmed.slice(6))
            if (event.type === 'chunk') {
              fullOutput += event.content
              setOutput(fullOutput)
            } else if (event.type === 'done') {
              fullOutput = event.output || fullOutput
              setOutput(fullOutput)
            } else if (event.type === 'error') {
              fullOutput = `Error: ${event.error}`
              setOutput(fullOutput)
              hadError = true
            }
          } catch {}
        }
      }

      // Flush remaining buffer
      if (buffer.trim()) {
        for (const line of buffer.split('\n')) {
          const trimmed = line.trim()
          if (!trimmed.startsWith('data: ')) continue
          try {
            const event = JSON.parse(trimmed.slice(6))
            if (event.type === 'chunk') {
              fullOutput += event.content
              setOutput(fullOutput)
            } else if (event.type === 'done') {
              fullOutput = event.output || fullOutput
              setOutput(fullOutput)
            } else if (event.type === 'error') {
              fullOutput = `Error: ${event.error}`
              setOutput(fullOutput)
              hadError = true
            }
          } catch {}
        }
      }

      const duration = Date.now() - startTimeRef.current
      const agentDisplay = currentAgent?.name || agentToUse || 'No Agent'

      setHistory(prev => [{
        id: `${Date.now()}-${Math.random().toString(36).slice(2, 6)}`,
        agent: agentToUse || '',
        agentName: agentDisplay,
        prompt: testPrompt,
        output: fullOutput,
        duration,
        status: (hadError ? 'error' : 'success') as const,
        timestamp: new Date(),
      }, ...prev].slice(0, 50))

    } catch (err: unknown) {
      const duration = Date.now() - startTimeRef.current
      if (err instanceof Error && err.name === 'AbortError') {
        setOutput(prev => prev ? prev + '\n\n---\n*Test cancelled by user*' : 'Test cancelled.')
      } else {
        const errMsg = err instanceof Error ? err.message : String(err)
        setOutput(`Error: ${errMsg}`)
        const agentDisplay = currentAgent?.name || agentToUse || 'No Agent'
        setHistory(prev => [{
          id: `${Date.now()}`,
          agent: agentToUse || '',
          agentName: agentDisplay,
          prompt: testPrompt,
          output: `Error: ${errMsg}`,
          duration,
          status: 'error',
          timestamp: new Date(),
        }, ...prev].slice(0, 50))
      }
    } finally {
      setRunning(false)
      abortRef.current = null
    }
  }, [prompt, selectedAgent, settings, currentAgent])

  const cancelRun = () => { abortRef.current?.abort() }

  // ─── Actions ──────────────────────────────────────────────────────────

  const copyOutput = () => {
    navigator.clipboard.writeText(output)
    toast('success', 'Copied to clipboard')
  }

  const exportOutput = () => {
    if (!output) return
    const name = currentAgent?.name || 'raw-prompt'
    const blob = new Blob([`# Playground Test: ${name}\n\n**Prompt:**\n${prompt}\n\n**Output:**\n${output}`], { type: 'text/markdown' })
    const url = URL.createObjectURL(blob)
    const a = document.createElement('a')
    a.href = url
    a.download = `playground-${name.toLowerCase().replace(/\s+/g, '-')}-${Date.now()}.md`
    a.click()
    URL.revokeObjectURL(url)
  }

  const loadFromHistory = (item: TestResult) => {
    setSelectedAgent(item.agent)
    setPrompt(item.prompt)
    setOutput(item.output)
  }

  const rerunFromHistory = (item: TestResult) => {
    setSelectedAgent(item.agent)
    setPrompt(item.prompt)
    runTest(item.prompt, item.agent)
  }

  const removeHistoryItem = (e: React.MouseEvent, id: string) => {
    e.stopPropagation()
    setHistory(prev => prev.filter(h => h.id !== id))
  }

  const clearHistory = () => {
    setHistory([])
    localStorage.removeItem(STORAGE_KEY)
  }

  const clearAll = () => {
    setOutput('')
    setPrompt('')
    setSelectedAgent('')
  }

  // ─── Keyboard ─────────────────────────────────────────────────────────

  const handlePromptKeyDown = (e: React.KeyboardEvent) => {
    if (e.key === 'Enter' && (e.metaKey || e.ctrlKey)) {
      e.preventDefault()
      runTest()
    }
  }

  // ─── Stats ────────────────────────────────────────────────────────────

  const successCount = history.filter(h => h.status === 'success').length
  const errorCount = history.filter(h => h.status === 'error').length
  const avgDuration = history.length > 0
    ? history.reduce((sum, h) => sum + h.duration, 0) / history.length
    : 0

  // ─── Render ───────────────────────────────────────────────────────────

  return (
    <div className="h-screen flex flex-col">
      {/* Header */}
      <div className="px-6 py-3.5 border-b border-border bg-surface shrink-0">
        <div className="flex items-center justify-between">
          <div>
            <h1 className="text-lg font-semibold flex items-center gap-2">
              <Sparkles className="w-5 h-5 text-accent" />
              Agent Playground
            </h1>
            <p className="text-[11px] text-text-muted mt-0.5">
              Test any agent with a prompt. Real-time streaming output.
              {history.length > 0 && (
                <span className="ml-2 text-text-secondary">
                  {successCount} passed · {errorCount} failed · avg {formatDuration(avgDuration)}
                </span>
              )}
            </p>
          </div>
          <div className="flex items-center gap-1.5">
            <button
              onClick={() => setShowSettings(!showSettings)}
              title="Settings"
              className={`p-2 rounded-lg transition-colors ${showSettings ? 'bg-accent-muted text-accent' : 'text-text-muted hover:text-text hover:bg-surface-2'}`}
            >
              <Settings2 className="w-4 h-4" />
            </button>
            <button
              onClick={clearAll}
              title="Clear editor"
              className="flex items-center gap-1.5 px-3 py-1.5 text-xs rounded-lg border border-border hover:bg-surface-2 transition-colors text-text-muted hover:text-text"
            >
              <Trash2 className="w-3.5 h-3.5" />
              Clear
            </button>
          </div>
        </div>

        {/* Settings Panel */}
        {showSettings && (
          <div className="mt-3 p-4 bg-surface-2 rounded-xl border border-border space-y-3">
            <div className="flex items-center justify-between">
              <p className="text-xs font-semibold text-text">Settings</p>
              <button onClick={() => setShowSettings(false)} className="p-1 text-text-muted hover:text-text">
                <X className="w-3.5 h-3.5" />
              </button>
            </div>
            <div className="grid grid-cols-2 gap-4">
              <div>
                <label className="text-[11px] font-medium text-text-muted block mb-1">Timeout</label>
                <select
                  value={settings.timeoutMs}
                  onChange={e => setSettings(s => ({ ...s, timeoutMs: Number(e.target.value) }))}
                  className="w-full bg-surface border border-border rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-accent/50"
                >
                  <option value={30000}>30 seconds</option>
                  <option value={60000}>1 minute</option>
                  <option value={120000}>2 minutes</option>
                  <option value={300000}>5 minutes</option>
                  <option value={600000}>10 minutes</option>
                </select>
              </div>
              <div>
                <label className="text-[11px] font-medium text-text-muted block mb-1">Output format</label>
                <select
                  value={settings.outputMode}
                  onChange={e => setSettings(s => ({ ...s, outputMode: e.target.value as 'markdown' | 'raw' }))}
                  className="w-full bg-surface border border-border rounded-lg px-3 py-2 text-xs focus:outline-none focus:border-accent/50"
                >
                  <option value="markdown">Markdown (rendered)</option>
                  <option value="raw">Raw text</option>
                </select>
              </div>
            </div>
            <div>
              <label className="text-[11px] font-medium text-text-muted block mb-1">
                Custom instructions override
                <span className="font-normal text-text-muted/70 ml-1">(replaces agent system prompt if set)</span>
              </label>
              <textarea
                value={settings.customInstructions}
                onChange={e => setSettings(s => ({ ...s, customInstructions: e.target.value }))}
                placeholder="Leave empty to use agent's default instructions..."
                className="w-full bg-surface border border-border rounded-lg px-3 py-2 text-xs font-mono resize-none focus:outline-none focus:border-accent/50 h-20"
              />
            </div>
          </div>
        )}
      </div>

      {/* Main Content */}
      <div className="flex-1 flex min-h-0">
        {/* Left: Input + History */}
        <div className="w-1/2 flex flex-col border-r border-border min-w-0">
          {/* Agent Picker */}
          <div className="px-5 py-3 border-b border-border shrink-0">
            <label className="text-[11px] font-medium text-text-muted block mb-1.5">Agent</label>
            <div className="relative" ref={agentPickerRef}>
              <button
                onClick={() => { setShowAgentPicker(!showAgentPicker); setAgentFilter('') }}
                className="w-full flex items-center justify-between px-3 py-2.5 rounded-xl bg-surface-2 border border-border text-sm text-text hover:border-accent/40 transition-colors"
              >
                <span className="flex items-center gap-2 min-w-0">
                  {currentAgent ? (
                    <>
                      <AgentIcon name={currentAgent.name} uid={`pg-${currentAgent.name}`} size={20} global={currentAgent.scope === 'global'} />
                      <span className="font-medium truncate">{currentAgent.name}</span>
                      <span className="text-[10px] text-text-muted shrink-0">({currentAgent.model})</span>
                    </>
                  ) : (
                    <span className="text-text-muted">No agent (raw prompt)</span>
                  )}
                </span>
                <ChevronDown className={`w-4 h-4 text-text-muted shrink-0 transition-transform ${showAgentPicker ? 'rotate-180' : ''}`} />
              </button>

              {showAgentPicker && (
                <div className="absolute top-full left-0 right-0 mt-1 bg-surface border border-border rounded-xl shadow-2xl z-20 max-h-[350px] flex flex-col overflow-hidden">
                  <div className="p-2 border-b border-border shrink-0">
                    <div className="relative">
                      <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-text-muted" />
                      <input
                        value={agentFilter}
                        onChange={e => setAgentFilter(e.target.value)}
                        placeholder="Search agents..."
                        className="w-full bg-surface-2 border border-border rounded-lg pl-8 pr-3 py-2 text-sm text-text focus:outline-none focus:border-accent/50"
                        autoFocus
                      />
                    </div>
                  </div>
                  <div className="overflow-y-auto flex-1">
                    {/* No Agent option */}
                    <button
                      onClick={() => { setSelectedAgent(''); setShowAgentPicker(false); setAgentFilter('') }}
                      className={`w-full flex items-center gap-2 px-3 py-2.5 text-sm hover:bg-surface-2 transition-colors ${!selectedAgent ? 'bg-accent-muted text-accent' : 'text-text-secondary'}`}
                    >
                      <span className="w-5 h-5 rounded-md bg-surface-3 flex items-center justify-center text-[10px] shrink-0">—</span>
                      <span>No Agent (raw prompt)</span>
                    </button>

                    {/* Global agents */}
                    {filteredGlobal.length > 0 && (
                      <>
                        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted px-3 pt-2 pb-1">
                          Global ({filteredGlobal.length})
                        </p>
                        {filteredGlobal.map(agent => (
                          <button
                            key={`g-${agent.filename}`}
                            onClick={() => { setSelectedAgent(agent.filename || agent.name); setShowAgentPicker(false); setAgentFilter('') }}
                            className={`w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-surface-2 transition-colors ${selectedAgent === agent.filename || selectedAgent === agent.name ? 'bg-accent-muted text-accent' : ''}`}
                          >
                            <AgentIcon name={agent.name} uid={`pick-g-${agent.name}`} size={20} global />
                            <div className="text-left min-w-0 flex-1">
                              <p className="font-medium truncate text-[12px]">{agent.name}</p>
                              <p className="text-[10px] text-text-muted truncate">{agent.description?.slice(0, 60)}</p>
                            </div>
                            <span className="text-[9px] text-text-muted shrink-0 font-mono">{agent.model}</span>
                          </button>
                        ))}
                      </>
                    )}

                    {/* Project agents */}
                    {filteredProject.length > 0 && (
                      <>
                        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted px-3 pt-2 pb-1">
                          Project ({filteredProject.length})
                        </p>
                        {filteredProject.map(agent => (
                          <button
                            key={`p-${agent.filename}-${agent.projectName}`}
                            onClick={() => { setSelectedAgent(agent.filename || agent.name); setShowAgentPicker(false); setAgentFilter('') }}
                            className={`w-full flex items-center gap-2 px-3 py-2 text-sm hover:bg-surface-2 transition-colors ${selectedAgent === agent.filename || selectedAgent === agent.name ? 'bg-accent-muted text-accent' : ''}`}
                          >
                            <AgentIcon name={agent.name} uid={`pick-p-${agent.name}`} size={20} global={false} />
                            <div className="text-left min-w-0 flex-1">
                              <p className="font-medium truncate text-[12px]">{agent.name}</p>
                              <p className="text-[10px] text-text-muted truncate">{agent.projectName}</p>
                            </div>
                            <span className="text-[9px] text-text-muted shrink-0 font-mono">{agent.model}</span>
                          </button>
                        ))}
                      </>
                    )}

                    {filteredAgents.length === 0 && agentFilter && (
                      <p className="text-xs text-text-muted text-center py-4">No agents match "{agentFilter}"</p>
                    )}
                  </div>
                </div>
              )}
            </div>

            {/* Agent description */}
            {currentAgent?.description && (
              <p className="text-[11px] text-text-muted mt-1.5 px-0.5 line-clamp-2">{currentAgent.description}</p>
            )}
          </div>

          {/* Prompt Input */}
          <div className="flex-1 flex flex-col px-5 py-3 min-h-0">
            <label className="text-[11px] font-medium text-text-muted mb-1.5">Test Prompt</label>
            <textarea
              value={prompt}
              onChange={e => setPrompt(e.target.value)}
              placeholder={currentAgent
                ? `Test "${currentAgent.name}" with a prompt...\n\ne.g. Write a Shopify App Store listing for Pinzo`
                : 'Enter a raw prompt to test without any agent...'
              }
              className="flex-1 bg-surface-2 border border-border rounded-xl px-4 py-3 text-sm text-text resize-none focus:outline-none focus:border-accent/50 transition-colors placeholder:text-text-muted font-mono min-h-[120px]"
              onKeyDown={handlePromptKeyDown}
            />
            <div className="flex items-center justify-between mt-2.5">
              <p className="text-[10px] text-text-muted">
                {prompt.length > 0 && <span className="text-text-secondary">{prompt.length} chars</span>}
                {prompt.length > 0 && ' · '}
                <kbd className="px-1 py-0.5 rounded bg-surface-2 border border-border text-[9px] font-mono">⌘Enter</kbd> to run
                {settings.customInstructions && (
                  <span className="ml-2 text-amber">· custom instructions active</span>
                )}
              </p>
              <div className="flex gap-2">
                {running ? (
                  <button
                    onClick={cancelRun}
                    className="flex items-center gap-1.5 px-3 py-2 bg-red/90 text-white rounded-xl text-xs font-medium hover:bg-red transition-colors"
                  >
                    <Square className="w-3 h-3 fill-current" />
                    Stop ({formatDuration(elapsedMs)})
                  </button>
                ) : (
                  <button
                    onClick={() => runTest()}
                    disabled={!prompt.trim()}
                    className="flex items-center gap-2 px-5 py-2 bg-accent text-white rounded-xl text-sm font-medium hover:bg-accent-hover disabled:opacity-40 disabled:cursor-not-allowed transition-colors"
                  >
                    <Play className="w-4 h-4" /> Run Test
                  </button>
                )}
              </div>
            </div>
          </div>

          {/* History */}
          <div className="border-t border-border shrink-0 max-h-[240px] flex flex-col">
            <div className="px-5 py-2 flex items-center justify-between shrink-0">
              <p className="text-[10px] font-semibold uppercase tracking-wider text-text-muted flex items-center gap-1.5">
                <Clock className="w-3 h-3" />
                History ({history.length})
              </p>
              <div className="flex items-center gap-1.5">
                {history.length > 3 && (
                  <div className="relative">
                    <Search className="absolute left-2 top-1/2 -translate-y-1/2 w-3 h-3 text-text-muted" />
                    <input
                      value={historyFilter}
                      onChange={e => setHistoryFilter(e.target.value)}
                      placeholder="Filter..."
                      className="w-28 bg-surface-2 border border-border rounded-md pl-6 pr-2 py-1 text-[10px] focus:outline-none focus:border-accent/50"
                    />
                  </div>
                )}
                {history.length > 0 && (
                  <button
                    onClick={clearHistory}
                    className="text-[10px] text-text-muted hover:text-red transition-colors px-1"
                    title="Clear all history"
                  >
                    Clear all
                  </button>
                )}
              </div>
            </div>
            <div className="flex-1 overflow-y-auto px-4 pb-2">
              {filteredHistory.length === 0 ? (
                <p className="text-[11px] text-text-muted text-center py-3">
                  {history.length === 0 ? 'No tests run yet.' : 'No matches.'}
                </p>
              ) : (
                <div className="space-y-0.5">
                  {filteredHistory.map(item => (
                    <div
                      key={item.id}
                      onClick={() => loadFromHistory(item)}
                      className="group flex items-center gap-2 px-2.5 py-2 rounded-lg hover:bg-surface-2 transition-colors cursor-pointer"
                    >
                      {item.status === 'success'
                        ? <CheckCircle className="w-3.5 h-3.5 text-green shrink-0" />
                        : <AlertCircle className="w-3.5 h-3.5 text-red shrink-0" />
                      }
                      <div className="min-w-0 flex-1">
                        <div className="flex items-center gap-1.5">
                          <p className="text-[11px] font-medium truncate">{item.agentName}</p>
                          <span className="text-[9px] text-text-muted">{formatTime(item.timestamp)}</span>
                        </div>
                        <p className="text-[10px] text-text-muted truncate">{item.prompt}</p>
                      </div>
                      <div className="flex items-center gap-1 shrink-0">
                        <span className="text-[10px] text-text-muted">{formatDuration(item.duration)}</span>
                        <button
                          onClick={(e) => { e.stopPropagation(); rerunFromHistory(item) }}
                          className="p-1 rounded opacity-0 group-hover:opacity-100 text-text-muted hover:text-accent transition-all"
                          title="Re-run this test"
                        >
                          <RotateCcw className="w-3 h-3" />
                        </button>
                        <button
                          onClick={(e) => removeHistoryItem(e, item.id)}
                          className="p-1 rounded opacity-0 group-hover:opacity-100 text-text-muted hover:text-red transition-all"
                          title="Remove from history"
                        >
                          <X className="w-3 h-3" />
                        </button>
                      </div>
                    </div>
                  ))}
                </div>
              )}
            </div>
          </div>
        </div>

        {/* Right: Output */}
        <div className="w-1/2 flex flex-col min-w-0 relative">
          {/* Output header */}
          <div className="flex items-center justify-between px-5 py-2.5 border-b border-border shrink-0">
            <p className="text-xs font-medium text-text-muted flex items-center gap-1.5">
              {running ? (
                <>
                  <Loader className="w-3.5 h-3.5 animate-spin text-purple" />
                  <span>Streaming... <span className="text-text-secondary font-mono">{formatDuration(elapsedMs)}</span></span>
                </>
              ) : output ? (
                <>
                  {output.startsWith('Error:') ? (
                    <><AlertCircle className="w-3.5 h-3.5 text-red" /> Error</>
                  ) : (
                    <><CheckCircle className="w-3.5 h-3.5 text-green" /> Output</>
                  )}
                  {history[0] && (
                    <span className="text-text-muted font-mono ml-1">({formatDuration(history[0].duration)})</span>
                  )}
                </>
              ) : (
                <><Terminal className="w-3.5 h-3.5" /> Output</>
              )}
            </p>
            <div className="flex items-center gap-1">
              {output && !running && (
                <>
                  <button
                    onClick={() => runTest()}
                    disabled={!prompt.trim()}
                    className="flex items-center gap-1 text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                    title="Re-run test"
                  >
                    <RotateCcw className="w-3 h-3" /> Re-run
                  </button>
                  <button
                    onClick={copyOutput}
                    className="flex items-center gap-1 text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                    title="Copy output"
                  >
                    <Copy className="w-3 h-3" /> Copy
                  </button>
                  <button
                    onClick={exportOutput}
                    className="flex items-center gap-1 text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                    title="Export as Markdown"
                  >
                    <Download className="w-3 h-3" /> Export
                  </button>
                  <button
                    onClick={() => setSettings(s => ({ ...s, outputMode: s.outputMode === 'markdown' ? 'raw' : 'markdown' }))}
                    className="text-[11px] text-text-muted hover:text-text px-2 py-1 rounded-lg hover:bg-surface-2 transition-colors"
                    title="Toggle output format"
                  >
                    {settings.outputMode === 'markdown' ? 'Raw' : 'Rendered'}
                  </button>
                </>
              )}
            </div>
          </div>

          {/* Output content */}
          <div ref={outputRef} className="flex-1 overflow-y-auto p-5">
            {output ? (
              settings.outputMode === 'markdown' ? (
                <div className="text-sm leading-relaxed">
                  <MarkdownRenderer content={output} />
                  {running && (
                    <span className="inline-block w-0.5 h-4 bg-purple animate-pulse ml-0.5 align-middle rounded-full" />
                  )}
                </div>
              ) : (
                <pre className="text-sm text-text whitespace-pre-wrap leading-relaxed font-mono break-words">
                  {output}
                  {running && (
                    <span className="inline-block w-0.5 h-4 bg-purple animate-pulse ml-0.5 align-middle rounded-full" />
                  )}
                </pre>
              )
            ) : (
              <div className="h-full flex flex-col items-center justify-center text-center">
                <div className="w-14 h-14 rounded-2xl bg-purple-muted flex items-center justify-center mb-3">
                  <Play className="w-6 h-6 text-purple" />
                </div>
                <p className="text-sm font-medium text-text-secondary mb-1">No output yet</p>
                <p className="text-xs text-text-muted max-w-[280px]">
                  Select an agent, write a test prompt, and click Run Test to see real-time streaming output.
                </p>
              </div>
            )}
          </div>

          {/* Scroll to bottom */}
          {showScrollBottom && output && (
            <div className="absolute bottom-4 right-4">
              <button
                onClick={() => outputRef.current?.scrollTo({ top: outputRef.current.scrollHeight, behavior: 'smooth' })}
                className="p-2 rounded-full bg-surface border border-border shadow-lg hover:bg-surface-2 transition-all text-text-muted hover:text-text"
              >
                <ArrowDown className="w-4 h-4" />
              </button>
            </div>
          )}
        </div>
      </div>
    </div>
  )
}

